-- Exact UTC nanosecond keys preserve ordering below SQLite datetime precision.
-- Legacy rows may omit both clocks; missing evidence is never synthesized.
CREATE TRIGGER email_telemetry_insert BEFORE INSERT ON email_deliveries
WHEN (json_extract(NEW.receipt,'$.unknown_since') IS NOT NULL AND (json_type(NEW.receipt,'$.unknown_since') IS NOT 'text' OR julianday(json_extract(NEW.receipt,'$.unknown_since')) IS NULL OR substr(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'),-1)!='Z' OR NOT (length(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'))=20 OR (length(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z')) BETWEEN 22 AND 30 AND substr(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'),20,1)='.' AND substr(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'),21,length(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'))-21) NOT GLOB '*[^0-9]*')) OR (substr(json_extract(NEW.receipt,'$.unknown_since'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.unknown_since'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.unknown_since'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) < (substr(json_extract(NEW.receipt,'$.command.approved_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.command.approved_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.command.approved_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9))))
 OR (json_extract(NEW.receipt,'$.last_observed_at') IS NOT NULL AND (json_type(NEW.receipt,'$.last_observed_at') IS NOT 'text' OR julianday(json_extract(NEW.receipt,'$.last_observed_at')) IS NULL OR substr(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'),-1)!='Z' OR NOT (length(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'))=20 OR (length(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z')) BETWEEN 22 AND 30 AND substr(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'),20,1)='.' AND substr(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'),21,length(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'))-21) NOT GLOB '*[^0-9]*')) OR (substr(json_extract(NEW.receipt,'$.last_observed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.last_observed_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.last_observed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) < (substr(json_extract(NEW.receipt,'$.command.approved_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.command.approved_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.command.approved_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9))))
 OR (json_extract(NEW.receipt,'$.last_observed_at') IS NOT NULL AND json_extract(NEW.receipt,'$.confirmed_at') IS NOT NULL AND (substr(json_extract(NEW.receipt,'$.last_observed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.last_observed_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.last_observed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) < (substr(json_extract(NEW.receipt,'$.confirmed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.confirmed_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.confirmed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)))
BEGIN SELECT RAISE(ABORT,'email observation clock conflict'); END;
CREATE TRIGGER email_telemetry_update BEFORE UPDATE ON email_deliveries
WHEN (json_extract(NEW.receipt,'$.unknown_since') IS NOT NULL AND (json_type(NEW.receipt,'$.unknown_since') IS NOT 'text' OR julianday(json_extract(NEW.receipt,'$.unknown_since')) IS NULL OR substr(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'),-1)!='Z' OR NOT (length(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'))=20 OR (length(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z')) BETWEEN 22 AND 30 AND substr(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'),20,1)='.' AND substr(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'),21,length(replace(json_extract(NEW.receipt,'$.unknown_since'),'+00:00','Z'))-21) NOT GLOB '*[^0-9]*')) OR (substr(json_extract(NEW.receipt,'$.unknown_since'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.unknown_since'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.unknown_since'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) < (substr(json_extract(NEW.receipt,'$.command.approved_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.command.approved_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.command.approved_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9))))
 OR (json_extract(NEW.receipt,'$.last_observed_at') IS NOT NULL AND (json_type(NEW.receipt,'$.last_observed_at') IS NOT 'text' OR julianday(json_extract(NEW.receipt,'$.last_observed_at')) IS NULL OR substr(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'),-1)!='Z' OR NOT (length(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'))=20 OR (length(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z')) BETWEEN 22 AND 30 AND substr(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'),20,1)='.' AND substr(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'),21,length(replace(json_extract(NEW.receipt,'$.last_observed_at'),'+00:00','Z'))-21) NOT GLOB '*[^0-9]*')) OR (substr(json_extract(NEW.receipt,'$.last_observed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.last_observed_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.last_observed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) < (substr(json_extract(NEW.receipt,'$.command.approved_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.command.approved_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.command.approved_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9))))
 OR (json_extract(NEW.receipt,'$.last_observed_at') IS NOT NULL AND json_extract(NEW.receipt,'$.confirmed_at') IS NOT NULL AND (substr(json_extract(NEW.receipt,'$.last_observed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.last_observed_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.last_observed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) < (substr(json_extract(NEW.receipt,'$.confirmed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.confirmed_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.confirmed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)))
 OR (json_extract(OLD.receipt,'$.unknown_since') IS NOT NULL AND (substr(json_extract(NEW.receipt,'$.unknown_since'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.unknown_since'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.unknown_since'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) IS NOT (substr(json_extract(OLD.receipt,'$.unknown_since'),1,19)||'.'||substr(CASE WHEN substr(json_extract(OLD.receipt,'$.unknown_since'),20,1)='.' THEN replace(replace(substr(json_extract(OLD.receipt,'$.unknown_since'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)))
 OR (json_extract(OLD.receipt,'$.last_observed_at') IS NOT NULL AND (json_extract(NEW.receipt,'$.last_observed_at') IS NULL OR (substr(json_extract(NEW.receipt,'$.last_observed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(NEW.receipt,'$.last_observed_at'),20,1)='.' THEN replace(replace(substr(json_extract(NEW.receipt,'$.last_observed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9)) < (substr(json_extract(OLD.receipt,'$.last_observed_at'),1,19)||'.'||substr(CASE WHEN substr(json_extract(OLD.receipt,'$.last_observed_at'),20,1)='.' THEN replace(replace(substr(json_extract(OLD.receipt,'$.last_observed_at'),21),'+00:00',''),'Z','') ELSE '' END||'000000000',1,9))))
BEGIN SELECT RAISE(ABORT,'email observation clock conflict'); END;
